create extension if not exists pgcrypto;
create table if not exists companies(id uuid primary key default gen_random_uuid(),name text not null,code text not null unique,created_at timestamptz default now());
create table customers(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id) on delete cascade,name text not null,code text not null,unique(company_id,code));
create table machines(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id) on delete cascade,brand text,code text not null,name text not null,unique(company_id,code));
create table shifts(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id) on delete cascade,code text not null,name text not null,start_time time not null,end_time time not null,excluded_planned_minutes numeric default 0,unique(company_id,code));
create table part_numbers(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id) on delete cascade,customer_id uuid not null references customers(id),part_number text not null,description text,cost_per_piece numeric default 0,scrap_cost numeric default 0,unique(company_id,part_number));
create table operations(id uuid primary key default gen_random_uuid(),part_number_id uuid not null references part_numbers(id) on delete cascade,operation_number text not null,description text,cycle_time_seconds numeric,unique(part_number_id,operation_number));
create table part_number_machines(part_number_id uuid references part_numbers(id) on delete cascade,machine_id uuid references machines(id) on delete cascade,primary key(part_number_id,machine_id));
create table defect_catalog(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id) on delete cascade,part_number_id uuid not null references part_numbers(id) on delete cascade,operation_number text not null,code text not null,defect text not null,category text check(category in('Dimensional','Visual','Material','Process')));
create table downtime_catalog(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id) on delete cascade,code text not null,downtime text not null,category text check(category in('Machine','Tooling','Quality','Setup','Personnel','Logistics','Material')),unique(company_id,code));
create table production_records(id uuid primary key default gen_random_uuid(),company_id uuid not null references companies(id) on delete cascade,captured_at timestamptz default now(),production_date date not null default current_date,shift_id uuid references shifts(id),lot_number text,customer_id uuid references customers(id),part_number_id uuid not null references part_numbers(id),machine_id uuid references machines(id),operation_number text,quantity_produced numeric not null default 0,operator_name text,supervisor_name text);
create table scrap_records(id uuid primary key default gen_random_uuid(),production_record_id uuid references production_records(id) on delete cascade,company_id uuid not null references companies(id) on delete cascade,defect_id uuid references defect_catalog(id),defect text not null,quantity numeric not null check(quantity>=0),reason text,cost numeric default 0);
create table downtime_records(id uuid primary key default gen_random_uuid(),production_record_id uuid references production_records(id) on delete cascade,company_id uuid not null references companies(id) on delete cascade,machine_id uuid references machines(id),downtime_id uuid references downtime_catalog(id),downtime text not null,minutes numeric not null check(minutes>=0),reason text,type text not null check(type in('Planned','Unplanned')));
create index on production_records(company_id,production_date);create index on scrap_records(company_id);create index on downtime_records(company_id);
create or replace view v_register_production as select p.id,p.captured_at,p.production_date,s.name shift,p.lot_number,c.name customer,pn.part_number,p.operation_number,p.quantity_produced,coalesce(sum(sr.quantity),0) quantity_scrap,case when p.quantity_produced>0 then round(100*(p.quantity_produced-coalesce(sum(sr.quantity),0))/p.quantity_produced,2) end yield from production_records p left join shifts s on s.id=p.shift_id left join customers c on c.id=p.customer_id join part_numbers pn on pn.id=p.part_number_id left join scrap_records sr on sr.production_record_id=p.id group by p.id,s.name,c.name,pn.part_number;
